}"},{"rank":2,"score":29.9412,"file_path":"internal/sem/provider.go","start_line":6310,"end_line":6350,"focus_line":6310,"snippet_start_line":6310,"snippet_end_line":6350,"symbol_start_line":6310,"symbol_end_line":6350,"language":"Go","kind":"function","symbol_id":"local/deathcode:Go:internal/sem/provider.go:function:graphqlSchemaResolverRelations","symbol_name":"graphqlSchemaResolverRelations","qualified_name":"graphqlSchemaResolverRelations","signature":"func graphqlSchemaResolverRelations(schemaFields, resolvers map[string][]SymbolRecord) []RelationRecord","signals":["body","symbol-name","graph:callers","complete-symbol"],"snippet":"func graphqlSchemaResolverRelations(schemaFields, resolvers map[string][]SymbolRecord) []RelationRecord {
